function enrichBaleAttributes(bale: BaleListing): BaleListing {
  const cat = (bale.categoryId || bale.category || '').toLowerCase();
  const sub = (bale.subCategoryId || '').toLowerCase();
  const title = (bale.title || '').toLowerCase();

  let garmentType = bale.garmentType;
  let targetGender = bale.targetGender || 'Unisex / Adult';
  let primaryFabric = bale.primaryFabric;

  if (!garmentType) {
    if (sub.includes('puffer') || title.includes('puffer')) garmentType = 'Puffers';
    else if (cat.includes('jacket') || title.includes('jacket') || title.includes('bomber')) garmentType = 'Jackets';
    else if (cat.includes('fleece') || title.includes('hoodie') || title.includes('sweatshirt')) garmentType = 'Sweatshirts & Hoodies';
    else if (cat.includes('denim') || title.includes('jeans') || title.includes('denim')) garmentType = 'Denim / Jeans';
    else if (cat.includes('overcoat') || title.includes('trench') || title.includes('coat')) garmentType = 'Overcoats & Trench';
    else if (cat.includes('shirt') || title.includes('shirt') || title.includes('flannel')) garmentType = 'Shirts';
    else if (cat.includes('pant') || title.includes('cargo') || title.includes('trouser')) garmentType = 'Pants & Cargo';
    else if (cat.includes('mink') || title.includes('blanket')) garmentType = 'Mink Blankets';
    else garmentType = 'Assorted Mix';
  }

  if (!primaryFabric) {
    if (garmentType === 'Puffers') primaryFabric = 'Heavy Down & Nylon';
    else if (garmentType === 'Sweatshirts & Hoodies') primaryFabric = '100% Cotton Fleece';
    else if (garmentType === 'Denim / Jeans') primaryFabric = 'Heavy Denim / Twill';
    else if (garmentType === 'Overcoats & Trench') primaryFabric = 'Wool & Cashmere Blend';
    else if (garmentType === 'Mink Blankets') primaryFabric = 'Polyester / Sherpa';
    else primaryFabric = bale.fabricComposition || 'Mixed Vintage Fabrics';
  }

  return {
    ...bale,
    garmentType,
    targetGender,
    primaryFabric,
  };
}

export function getBaleBySlug(slug: string): BaleListing | undefined {
  const found = MOCK_BALES.find((bale) => bale.slug === slug || bale.id === slug);
  if (found) return enrichBaleAttributes(found);
  // Fallback match by partial slug or id
  const fallback = MOCK_BALES.find((bale) => slug.includes(bale.id) || bale.slug.includes(slug)) || MOCK_BALES[0];
  return fallback ? enrichBaleAttributes(fallback) : undefined;
}


export function getOrderById(orderId: string): EscrowOrderRecord | undefined {
  return MOCK_ORDERS[orderId] || Object.values(MOCK_ORDERS).find((o) => o.orderNumber === orderId || o.id === orderId);
}

export function getBalesByCategory(category: string, subCategory?: string): BaleListing[] {
  if (!category || category === 'all') {
    if (subCategory && subCategory !== 'all') {
      return MOCK_BALES.filter((bale) => bale.subCategoryId === subCategory);
    }
    return MOCK_BALES;
  }

  return MOCK_BALES.filter((bale) => {
    const matchesCategory = 
      bale.categoryId === category ||
      bale.category === category ||
      (category === 'korean_heavy_puffers' && bale.categoryId === 'winter-jackets-outerwear') ||
      (category === 'vintage_denim_workwear' && bale.categoryId === 'jeans-denim-workwear') ||
      (category === 'heavy_fleece_hoodies' && bale.categoryId === 'fleece-sweatshirts') ||
      (category === 'woolen_overcoats_trench' && bale.categoryId === 'overcoats-trench') ||
      (category === 'mink_fleece_blankets' && bale.categoryId === 'home-furnishings-mink') ||
      (category === 'curated_handpicked_lots' && (bale.sourcingMode === 'pieces_only' || bale.sourcingMode === 'both'));

    if (!matchesCategory) return false;
    if (subCategory && subCategory !== 'all') {
      return bale.subCategoryId === subCategory;
    }
    return true;
  });
}

export function searchBales(query: string, category: string = 'all', subCategory?: string): BaleListing[] {
  let filtered = getBalesByCategory(category, subCategory);
  if (!query.trim()) return filtered;
  
  const q = query.toLowerCase();
  return filtered.filter(
    (bale) =>
      bale.title.toLowerCase().includes(q) ||
      bale.shortDescription.toLowerCase().includes(q) ||
      bale.originCountry.toLowerCase().includes(q) ||
      bale.seller.maskedCode.toLowerCase().includes(q) ||
      bale.tags.some((tag) => tag.toLowerCase().includes(q))
  );
}

export function getAllSellerSlugs(): string[] {
  const slugs = new Set<string>();
  Object.values(MASKED_SELLERS).forEach((s) => {
    if (s.slug) slugs.add(s.slug);
    const gen = getSellerSlug(s.fullName, s.maskedCode);
    if (gen) slugs.add(gen);
  });
  return Array.from(slugs);
}

export function getSellerBySlug(slug: string): MaskedSeller | undefined {
  if (!slug) return undefined;
  const clean = slug.toLowerCase().trim();

  // 1. Direct match on slug
  const direct = Object.values(MASKED_SELLERS).find((s) => s.slug?.toLowerCase() === clean);
  if (direct) return direct;

  // 2. Computed slug match
  const computed = Object.values(MASKED_SELLERS).find((s) => {
    const sSlug = getSellerSlug(s.fullName, s.maskedCode);
    return sSlug.toLowerCase() === clean;
  });
  if (computed) return computed;

  // 3. Fallback matching code in slug (e.g. "pnp-001")
  const matchedSeller = Object.values(MASKED_SELLERS).find((s) => {
    const codeKey = s.maskedCode.toLowerCase().replace('#', '');
    return clean.includes(codeKey) || s.id.toLowerCase() === clean;
  });
  return matchedSeller;
}

export function getBalesBySeller(sellerIdOrSlug: string): BaleListing[] {
  if (!sellerIdOrSlug) return [];
  const clean = sellerIdOrSlug.toLowerCase().trim();

  const seller = getSellerBySlug(clean);
  const targetId = seller?.id.toLowerCase() || clean;
  const targetCode = seller?.maskedCode.toLowerCase() || '';

  return MOCK_BALES.filter((bale) => {
    const baleSellerId = bale.seller.id.toLowerCase();
    const baleSellerCode = bale.seller.maskedCode.toLowerCase();
    const baleSellerSlug = bale.seller.slug?.toLowerCase() || getSellerSlug(bale.seller.fullName, bale.seller.maskedCode);

    return (
      baleSellerId === targetId ||
      baleSellerCode === targetCode ||
      baleSellerSlug === clean ||
      clean.includes(baleSellerCode.replace('#', ''))
    );
  });
}

